const svg=$('#qb-svg'), out=$('#qb-out');
const th=$('#qb-th'), thL=$('#qb-th-lbl'), ph=$('#qb-ph'), phL=$('#qb-ph-lbl');
const cx=320, cy=150, R=110;
function render(){
  svg.innerHTML='';
  const theta=+th.value, phi=+ph.value;
  thL.textContent='θ = '+(theta/Math.PI).toFixed(2)+'π';
  phL.textContent='φ = '+(phi/Math.PI).toFixed(2)+'π';
  // sphere outline + equator ellipse + axes
  svg.appendChild(SVG('circle',{cx:cx,cy:cy,r:R,fill:'none',stroke:'var(--line)','stroke-width':1.5}));
  svg.appendChild(SVG('ellipse',{cx:cx,cy:cy,rx:R,ry:R*0.32,fill:'none',stroke:'var(--line)','stroke-dasharray':'3 3'}));
  svg.appendChild(SVG('line',{x1:cx,y1:cy-R-12,x2:cx,y2:cy+R+12,stroke:'var(--line)'}));
  const lab=function(x,y,t,c,anc){const e=SVG('text',{x:x,y:y,'text-anchor':anc||'middle','font-size':13,fill:c});e.textContent=t;svg.appendChild(e);};
  lab(cx,cy-R-18,'|0⟩','var(--yellow)'); lab(cx,cy+R+24,'|1⟩','var(--yellow)');
  // oblique projection of the Bloch vector (x right, z up, y into-page via 0.32 tilt)
  const x=Math.sin(theta)*Math.cos(phi), y=Math.sin(theta)*Math.sin(phi), z=Math.cos(theta);
  const px=cx + R*x, py=cy - R*z + R*y*0.32;
  svg.appendChild(SVG('line',{x1:cx,y1:cy,x2:px,y2:py,stroke:'var(--cyan)','stroke-width':2.5}));
  svg.appendChild(SVG('circle',{cx:px,cy:py,r:5,fill:'var(--cyan)'}));
  const c2=Math.cos(theta/2), s2=Math.sin(theta/2);
  out.textContent='|ψ⟩ = cos(θ/2)|0⟩ + e^{iφ} sin(θ/2)|1⟩\n'
    +'      = '+c2.toFixed(3)+' |0⟩ + ('+ (Math.cos(phi)*s2).toFixed(3)+' + '+(Math.sin(phi)*s2).toFixed(3)+'i)|1⟩\n'
    +'Bloch vector (x,y,z) = ('+x.toFixed(2)+', '+y.toFixed(2)+', '+z.toFixed(2)+')\n'
    +'measurement probabilities:  P(0) = cos²(θ/2) = '+(c2*c2).toFixed(3)+',   P(1) = sin²(θ/2) = '+(s2*s2).toFixed(3);
}
th.addEventListener('input',render); ph.addEventListener('input',render); render();

const svg=$('#gt-svg'), out=$('#gt-out');
const th=$('#gt-th'), thL=$('#gt-th-lbl');
const R2=Math.SQRT1_2;
// state = [re0,im0,re1,im1]
let st=[1,0,0,0], hist=[];
function prepare(){ const t=+th.value; thL.textContent='input |ψ⟩: θ = '+(t/Math.PI).toFixed(2)+'π'; st=[Math.cos(t/2),0,Math.sin(t/2),0]; hist=[]; render(); }
function applyU(name){
  const a=[st[0],st[1]], b=[st[2],st[3]];
  let na=a.slice(), nb=b.slice();
  if(name==='X'){ na=b.slice(); nb=a.slice(); }
  else if(name==='Z'){ nb=[-b[0],-b[1]]; }
  else if(name==='H'){ na=[(a[0]+b[0])*R2,(a[1]+b[1])*R2]; nb=[(a[0]-b[0])*R2,(a[1]-b[1])*R2]; }
  else if(name==='S'){ nb=[-b[1],b[0]]; }                 // multiply b by i
  else if(name==='T'){ const c=Math.cos(Math.PI/4),s=Math.sin(Math.PI/4); nb=[b[0]*c-b[1]*s, b[0]*s+b[1]*c]; }
  if(name==='reset'){ prepare(); return; }
  st=[na[0],na[1],nb[0],nb[1]];
  hist.push(name);
  render();
}
function fmt(re,im){ const r=Math.abs(re)<1e-9?0:re, i=Math.abs(im)<1e-9?0:im;
  return r.toFixed(3)+(i>=0?' + ':' - ')+Math.abs(i).toFixed(3)+'i'; }
function render(){
  svg.innerHTML='';
  const p0=st[0]*st[0]+st[1]*st[1], p1=st[2]*st[2]+st[3]*st[3];
  // amplitude bars
  const bx=120, bw=120, base=150, h=110;
  const lab=function(x,y,t,c,anc){const e=SVG('text',{x:x,y:y,'text-anchor':anc||'middle','font-size':12,fill:c});e.textContent=t;svg.appendChild(e);};
  svg.appendChild(SVG('rect',{x:bx,y:base-p0*h,width:bw,height:p0*h,fill:'var(--yellow)','fill-opacity':0.55}));
  svg.appendChild(SVG('rect',{x:bx+200,y:base-p1*h,width:bw,height:p1*h,fill:'var(--violet)','fill-opacity':0.55}));
  svg.appendChild(SVG('line',{x1:60,y1:base,x2:560,y2:base,stroke:'var(--line)'}));
  lab(bx+bw/2,base+18,'|0⟩','var(--yellow)'); lab(bx+200+bw/2,base+18,'|1⟩','var(--violet)');
  lab(bx+bw/2,base-p0*h-6,'P='+p0.toFixed(3),'var(--mute)'); lab(bx+200+bw/2,base-p1*h-6,'P='+p1.toFixed(3),'var(--mute)');
  lab(300,28,'circuit:  |ψ₀⟩ — '+(hist.length?hist.join(' — '):'(no gates)'),'var(--cyan)');
  out.textContent='state vector:\n  α = '+fmt(st[0],st[1])+'   (amplitude of |0⟩)\n  β = '+fmt(st[2],st[3])+'   (amplitude of |1⟩)\n'
    +'probabilities:  P(0) = '+p0.toFixed(3)+',  P(1) = '+p1.toFixed(3)+'   (sum = '+(p0+p1).toFixed(3)+')\n'
    +'gates applied: '+(hist.length?hist.join(', '):'none yet — input state set by the θ slider');
}
['X','H','Z','S','T','reset'].forEach(function(g){ const btn=$('#gt-'+g.toLowerCase()); if(btn) btn.addEventListener('click',function(){applyU(g);}); });
th.addEventListener('input',prepare); prepare();

const svg=$('#en-svg'), out=$('#en-out');
const th=$('#en-th'), thL=$('#en-th-lbl');
function render(){
  svg.innerHTML='';
  const theta=+th.value; thL.textContent='θ = '+(theta/Math.PI).toFixed(3)+'π';
  const c=Math.cos(theta), s=Math.sin(theta);
  const amps=[c,0,0,s], labs=['|00⟩','|01⟩','|10⟩','|11⟩'];
  const base=150, h=110, x0=120, gap=110, bw=70;
  const lab=function(x,y,t,col,anc){const e=SVG('text',{x:x,y:y,'text-anchor':anc||'middle','font-size':12,fill:col});e.textContent=t;svg.appendChild(e);};
  svg.appendChild(SVG('line',{x1:80,y1:base,x2:560,y2:base,stroke:'var(--line)'}));
  for(let i=0;i<4;i++){ const p=amps[i]*amps[i];
    svg.appendChild(SVG('rect',{x:x0+i*gap,y:base-p*h,width:bw,height:p*h,fill:'var(--cyan)','fill-opacity':0.5}));
    lab(x0+i*gap+bw/2,base+18,labs[i],'var(--mute)');
    lab(x0+i*gap+bw/2,base-p*h-6,p.toFixed(2),'var(--mute)');
  }
  const l0=c*c, l1=s*s;
  const ent=function(p){ return p<=1e-12?0:-p*Math.log2(p); };
  const S=ent(l0)+ent(l1);
  const conc=Math.abs(Math.sin(2*theta));
  let verdict; if(theta<1e-3||Math.abs(theta-Math.PI/2)<1e-3) verdict='PRODUCT state (separable, S=0)';
    else if(Math.abs(theta-Math.PI/4)<1e-3) verdict='maximally entangled Bell state (S=1 bit)';
    else verdict='partially entangled';
  out.textContent='|ψ⟩ = cos θ |00⟩ + sin θ |11⟩\n'
    +'reduced state of qubit A:  ρ_A = diag(cos²θ, sin²θ) = diag('+l0.toFixed(3)+', '+l1.toFixed(3)+')\n'
    +'entanglement entropy  S(ρ_A) = '+S.toFixed(3)+' bits;   concurrence |sin 2θ| = '+conc.toFixed(3)+'\n'
    +'→ '+verdict;
}
th.addEventListener('input',render); render();

const svg=$('#ms-svg'), out=$('#ms-out');
const th=$('#ms-th'), thL=$('#ms-th-lbl');
let basis='Z';
function render(){
  svg.innerHTML='';
  const theta=+th.value; thL.textContent='θ = '+(theta/Math.PI).toFixed(2)+'π';
  const a=Math.cos(theta/2), b=Math.sin(theta/2);   // real state cos|0>+sin|1>
  let p0,p1,l0,l1;
  if(basis==='Z'){ p0=a*a; p1=b*b; l0='0'; l1='1'; }
  else { const pp=(a+b)/Math.SQRT2, pm=(a-b)/Math.SQRT2; p0=pp*pp; p1=pm*pm; l0='+'; l1='−'; }
  // simulate N draws
  const N=400; let c0=0; for(let i=0;i<N;i++) if(Math.random()<p0) c0++; const c1=N-c0;
  const base=160, h=110, lab=function(x,y,t,col,anc){const e=SVG('text',{x:x,y:y,'text-anchor':anc||'middle','font-size':12,fill:col});e.textContent=t;svg.appendChild(e);};
  svg.appendChild(SVG('line',{x1:80,y1:base,x2:560,y2:base,stroke:'var(--line)'}));
  // Born prob bars (outline) + sampled fraction (filled)
  const draw=function(x,p,frac,labtxt){
    svg.appendChild(SVG('rect',{x:x,y:base-p*h,width:120,height:p*h,fill:'none',stroke:'var(--yellow)','stroke-width':2}));
    svg.appendChild(SVG('rect',{x:x,y:base-frac*h,width:120,height:frac*h,fill:'var(--cyan)','fill-opacity':0.45}));
    lab(x+60,base+18,labtxt,'var(--mute)');
    lab(x+60,base-Math.max(p,frac)*h-6,'P='+p.toFixed(3),'var(--mute)');
  };
  draw(160,p0,c0/N,'|'+l0+'⟩'); draw(360,p1,c1/N,'|'+l1+'⟩');
  lab(300,28,'measuring in the '+basis+' basis   (yellow outline = Born P, cyan = '+N+' samples)','var(--cyan)');
  out.textContent='state |ψ⟩ = cos(θ/2)|0⟩ + sin(θ/2)|1⟩,  measured in the '+basis+' basis\n'
    +'Born-rule probabilities:  P(|'+l0+'⟩) = '+p0.toFixed(3)+',   P(|'+l1+'⟩) = '+p1.toFixed(3)+'\n'
    +'sampled frequencies ('+N+' shots):  '+(c0/N).toFixed(3)+' / '+(c1/N).toFixed(3)+'\n'
    +'no-cloning: you cannot copy |ψ⟩ to learn these amplitudes from one shot — each run yields a single collapsed outcome.';
}
th.addEventListener('input',render);
const bz=$('#ms-bz'), bx=$('#ms-bx');
if(bz) bz.addEventListener('click',function(){basis='Z'; bz.classList.add('active'); if(bx)bx.classList.remove('active'); render();});
if(bx) bx.addEventListener('click',function(){basis='X'; bx.classList.add('active'); if(bz)bz.classList.remove('active'); render();});
if(bz) bz.classList.add('active');
render();

const svg=$('#gr-svg'), out=$('#gr-out');
const kk=$('#gr-k'), kL=$('#gr-k-lbl');
const N=16, theta=Math.asin(1/Math.sqrt(N));
function render(){
  svg.innerHTML='';
  const k=Math.round(+kk.value); kL.textContent='Grover iterations k = '+k;
  const base=170, h=120, x0=70, gap=58, bw=40;
  const lab=function(x,y,t,col,anc){const e=SVG('text',{x:x,y:y,'text-anchor':anc||'middle','font-size':11,fill:col});e.textContent=t;svg.appendChild(e);};
  svg.appendChild(SVG('line',{x1:50,y1:base,x2:560,y2:base,stroke:'var(--line)'}));
  let best=0,bestp=0;
  for(let i=0;i<=8;i++){ const p=Math.pow(Math.sin((2*i+1)*theta),2); if(p>bestp){bestp=p;best=i;}
    svg.appendChild(SVG('rect',{x:x0+i*gap,y:base-p*h,width:bw,height:p*h,fill:(i===k?'var(--yellow)':'var(--violet)'),'fill-opacity':(i===k?0.85:0.4)}));
    lab(x0+i*gap+bw/2,base+16,i,'var(--mute)');
  }
  lab(300,26,'success probability sin²((2k+1)θ) over Grover iterations  (N = 16)','var(--cyan)');
  lab(300,base+34,'iterations k','var(--mute)');
  const p=Math.pow(Math.sin((2*k+1)*theta),2);
  out.textContent='unstructured search over N = '+N+' items, one marked;  sin θ = 1/√N = '+(1/Math.sqrt(N)).toFixed(4)+'\n'
    +'success probability after k = '+k+' iterations:  sin²((2k+1)θ) = '+p.toFixed(4)+'\n'
    +'optimal k ≈ (π/4)√N − 1/2 = '+((Math.PI/4)*Math.sqrt(N)-0.5).toFixed(2)+'  → best integer k = '+best+' (P = '+bestp.toFixed(4)+')\n'
    +'classical search needs ~N/2 = '+(N/2)+' queries on average; Grover needs Θ(√N) — a quadratic speedup.';
}
kk.addEventListener('input',render); render();

const svg=$('#qec-svg'), out=$('#qec-out');
const ev=$('#qec-e'), evL=$('#qec-e-lbl');
let err=-1; // -1 none, else flipped qubit index
function syndrome(e){ // returns [s01, s12] in {+1,-1}; bit-flip on qubit e flips physical bits
  const flip=[0,0,0]; if(e>=0) flip[e]=1;
  const s01=(flip[0]^flip[1])?-1:1;
  const s12=(flip[1]^flip[2])?-1:1;
  return [s01,s12];
}
function diagnose(s){ const a=s[0],b=s[1];
  if(a===1&&b===1) return -1; if(a===-1&&b===1) return 0; if(a===-1&&b===-1) return 1; return 2; }
function render(){
  svg.innerHTML='';
  err=Math.round(+ev.value)-1; // 0->none(-1), 1->q0, 2->q1, 3->q2
  evL.textContent = (err<0?'error: none':'error: bit-flip on q'+err);
  const lab=function(x,y,t,col,anc){const e=SVG('text',{x:x,y:y,'text-anchor':anc||'middle','font-size':13,fill:col});e.textContent=t;svg.appendChild(e);};
  const xs=[160,320,480], y=110;
  for(let i=0;i<3;i++){
    const flipped=(err===i);
    svg.appendChild(SVG('circle',{cx:xs[i],cy:y,r:26,fill:flipped?'var(--pink)':'var(--panel2)',stroke:flipped?'var(--pink)':'var(--cyan)','stroke-width':2}));
    lab(xs[i],y+5,'q'+i,'#fff'); lab(xs[i],y-40,flipped?'flipped':'ok',flipped?'var(--pink)':'var(--mute)');
  }
  const s=syndrome(err), diag=diagnose(s);
  lab(240,180,'Z₀Z₁ = '+(s[0]>0?'+1':'−1'),'var(--yellow)');
  lab(400,180,'Z₁Z₂ = '+(s[1]>0?'+1':'−1'),'var(--yellow)');
  out.textContent='logical qubit encoded as  α|000⟩ + β|111⟩  (3-qubit bit-flip code)\n'
    +'syndrome  (Z₀Z₁, Z₁Z₂) = ('+(s[0]>0?'+1':'−1')+', '+(s[1]>0?'+1':'−1')+')\n'
    +(err<0 ? 'diagnosis: no error detected — logical state intact.'
           : 'diagnosis: bit-flip on qubit '+diag+' → reapply X on q'+diag+' to correct. Logical α,β never measured, so the superposition survives.');
}
ev.addEventListener('input',render); render();
